export const createImageMessageFromFullPath = function (imageFullPath : string, operationID ?: string | null) : Promise<OpenIMMessageItem | null> {
  return new Promise<OpenIMMessageItem | null>((resolve, reject) => {
    const op = normalizeOperationID(operationID)
    if (requireLoggedInForCreate('createImageMessageFromFullPath', op, reject) == false) { return }
    if (rejectUnsupportedIOSLocalMediaPath('createImageMessageFromFullPath', imageFullPath, reject)) { return }
    resolve(parseNativeMessage(NativeOpenIMSDK.createImageMessageFromFullPath(op, normalizeIOSLocalMediaPath(imageFullPath))))
  })
}

export const createSoundMessageFromFullPath = function (params : OpenIMCreateSoundMessageParams, operationID ?: string | null) : Promise<OpenIMMessageItem | null> {
  return new Promise<OpenIMMessageItem | null>((resolve, reject) => {
    const op = normalizeOperationID(operationID)
    if (requireLoggedInForCreate('createSoundMessageFromFullPath', op, reject) == false) { return }
    if (rejectUnsupportedIOSLocalMediaPath('createSoundMessageFromFullPath', params.soundPath, reject)) { return }
    resolve(parseNativeMessage(NativeOpenIMSDK.createSoundMessageFromFullPath(op, normalizeIOSLocalMediaPath(params.soundPath), params.duration)))
  })
}

export const createVideoMessageFromFullPath = function (params : OpenIMCreateVideoMessageParams, operationID ?: string | null) : Promise<OpenIMMessageItem | null> {
  return new Promise<OpenIMMessageItem | null>((resolve, reject) => {
    const op = normalizeOperationID(operationID)
    if (requireLoggedInForCreate('createVideoMessageFromFullPath', op, reject) == false) { return }
    if (rejectUnsupportedIOSLocalMediaPath('createVideoMessageFromFullPath', params.videoPath, reject)) { return }
    if (rejectUnsupportedIOSLocalMediaPath('createVideoMessageFromFullPath', params.snapshotPath, reject)) { return }
    resolve(parseNativeMessage(NativeOpenIMSDK.createVideoMessageFromFullPath(op, normalizeIOSLocalMediaPath(params.videoPath), params.videoType, params.duration, normalizeIOSLocalMediaPath(params.snapshotPath))))
  })
}

export const createFileMessageFromFullPath = function (params : OpenIMCreateFileMessageParams, operationID ?: string | null) : Promise<OpenIMMessageItem | null> {
  return new Promise<OpenIMMessageItem | null>((resolve, reject) => {
    const op = normalizeOperationID(operationID)
    if (requireLoggedInForCreate('createFileMessageFromFullPath', op, reject) == false) { return }
    if (rejectUnsupportedIOSLocalMediaPath('createFileMessageFromFullPath', params.filePath, reject)) { return }
    resolve(parseNativeMessage(NativeOpenIMSDK.createFileMessageFromFullPath(op, normalizeIOSLocalMediaPath(params.filePath), params.fileName)))
  })
}

